            running += x
            running_mod = running % k
            # Cost contribution: we need running_mod to be 0 or 
            # we need to find nearest position where it can balance
            # Optimal: cost is min(running_mod, k - running_mod) for each position
            cost += min(running_mod, k - running_mod)
        return cost

    # Better approach: use actual current position logic
    def compute_cost_v2(arr, k):
        cost = 0
        prefix_mod = 0
        for x in arr:
            prefix_mod = (prefix_mod + x) % k
            # The cost contributed by this prefix mod value is prefix_mod
