        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                if i > 1:
                    divs.append(i)
                if i != x // i and x // i > 1:
                    divs.append(x // i)
        return divs

    divisors = get_divisors(total)

    if not divisors:
        return "-1\n"

    def compute_cost(arr, k):
        cost = 0
        prefix = 0
        for x in arr:
            prefix = (prefix + x) % k
            cost += prefix
        return cost

    ans = float('inf')
    for k in divisors:
