        x = x_prime / 100000.0
        ops.append((t, x, y))

    # dp: set of reachable values after each time step
    dp = {0}

    # Track earliest time for each value
    earliest = {0: 0}

    for step, (t, x, y) in enumerate(ops, 1):
        new_dp = set()
        for val in dp:
            # Option 1: don't apply operation (a=0)
            new_dp.add(val)

            # For Type 1: k := ceil(k + x), apply a times
            if t == 1:
                start_val = val
                curr = start_val
                for a in range(1, y + 1):
                    # Apply one more time
                    prev = curr
                    curr = int(-(-prev + x))  # ceil(x) using negative trick
                    if curr > m:
