def solution(input_data):
    import sys
    from collections import deque

    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Target value
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n < n:
        sqrt_n += 1

    # BFS to get parent pointers, depths, and BFS tree levels
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    level_nodes = [[] for _ in range(n + 1)]  # nodes at each BFS depth

    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True

    bfs_tree_order = [1]

    # For finding cycles during BFS
    best_cycle = []

    # BFS traversal
    while queue:
        u = queue.popleft()

        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                level_nodes[depth[v]].append(v)
                queue.append(v)
            elif v != parent[u] and depth[v] >= depth[u] - 1:
                # Potential back edge
                # Check if cycle length is >= sqrt_n
                cycle_len = depth[u] - depth[v] + 1
                if cycle_len >= sqrt_n:
                    # Construct cycle
                    best_cycle = [v]
                    curr = u
                    while curr != v:
                        best_cycle.append(curr)
                        curr = parent[curr]
                    best_cycle.reverse()

    if best_cycle:
        root = best_cycle[0]
        return "2\n{}\n{}".format(len(best_cycle), ' '.join(map(str, best_cycle)))

    # If no large cycle found by BFS back-edge, try DFS approach for better cycle detection
    # or we can use BFS tree levels to find independent set

    # Group nodes by depth
    levels = {}
    for v in range(1, n + 1):
        d = depth[v]
        if d not in levels:
            levels[d] = []
        levels[d].append(v)

    # Try to find independent set using different coloring
    # Option 1: layer-based (pick from nodes at same depth - but may not be independent)
    # Option 2: bipartite layers (nodes at depth % 2 == 1)

    odd_set = []
    for v in range(1, n + 1):
        if depth[v] % 2 == 1:
            odd_set.append(v)

    # Check if odd_set is actually independent (should be for bipartite, but this graph might not be bipartite)
    is_independent = True
    for i in range(len(odd_set)):
        for j in range(i+1, len(odd_set)):
            u, v = odd_set[i], odd_set[j]
            if v in adj[u]:
                is_independent = False
                break
        if not is_independent:
            break

    if is_independent and len(odd_set) >= sqrt_n:
        return "1\n{}".format(' '.join(map(str, odd_set)))

    # Try even depths
    even_set = [v for v in range(1, n + 1) if depth[v] % 2 == 0]

    is_independent = True
    for i in range(len(even_set)):
        for j in range(i+1, len(even_set)):
            u, v = even_set[i], even_set[j]
            if v in adj[u]:
                is_independent = False
                break
        if not is_independent:
            break

    if is_independent and len(even_set) >= sqrt_n:
        return "1\n{}".format(' '.join(map(str, even_set)))

    # If odd/even doesn't work, try to find any valid independent set
    # Greedy approach: pick node, mark neighbors as unavailable

    available = [True] * (n + 1)
    result = []

    for start in range(1, n + 1):
        if not available[start]:
            continue

        result.append(start)
        for v in adj[start]:
            available[v] = False

    if len(result) >= sqrt_n:
        return "1\n{}".format(' '.join(map(str, result)))

    # BFS-based independent set from deepest levels
    # Take nodes from deepest levels
    max_depth = max(depth[1:]) if n > 0 else 0

    # Collect nodes by depth
    depth_to_nodes = {d: [] for d in range(max_depth + 1)}
    for v in range(1, n + 1):
        depth_to_nodes[depth[v]].append(v)

    # Try consecutive depth layers (depth i and i+1 are not connected in BFS tree)
    # Actually consecutive levels CAN have edges, but same level shouldn't have parent-child

    # Since BFS tree levels guarantee parent-child only, same level nodes are siblings
    # siblings may have edges, so they're not guaranteed independent

    # Try: from each depth level, pick greedy independent subset
    for start_level in range(max_depth + 1):
        candidates = depth_to_nodes[start_level]
        if not candidates:
            continue

        # Greedy independent set from this level
        level_iso = []
        remaining = list(candidates)

        while remaining:
            node = remaining[0]
            level_iso.append(node)

            # Remove node and its neighbors from remaining
            new_remaining = []
            for r in remaining[1:]:
                if r not in adj[node]:
                    new_remaining.append(r)
            remaining = new_remaining

        if len(level_iso) >= sqrt_n:
            return "1\n{}".format(' '.join(map(str, level_iso)))

    # If we still fail, try a smarter cycle detection with DFS
    # Construct DFS tree and detect back edges

    sys.setrecursionlimit(max(300000, n + 500))

    dfs_parent = [0] * (n + 1)
    dfs_depth = [0] * (n + 1)
    dfs_visited = [False] * (n + 1)

    dfs_cycle = []
    dfs_found = [False]

    def dfs(u):
        if dfs_found[0]:
            return
        dfs_visited[u] = True
        dfs_depth[u] = dfs_depth[dfs_parent[u]] + 1 if dfs_parent[u] else 0

        for v in adj[u]:
            if dfs_parent[u] == v:
                continue
            if not dfs_visited[v]:
                dfs_parent[v] = u
                dfs(v)
                if dfs_found[0]:
                    return
            else:
                # Back edge found
                cycle_len = dfs_depth[u] - dfs_depth[v] + 1
                if cycle_len >= sqrt_n:
                    dfscycle = [v]
                    curr = u
                    while curr != v:
                        dfscycle.append(curr)
                        curr = dfs_parent[curr]
                    dfs_found[0] = True
                    dfs_cycle = cycle_len, dfscycle

    dfs(1)

    if dfs_found[0]:
        return "2\n{}\n{}".format(dfs_cycle[1], ' '.join(map(str, dfs_cycle[0])))

    # Final fallback: try collecting leaves or greedy independent set
    # Just return the greedy independent set we've been building
    final_iso = []
    temp_avail = [True] * (n + 1)

    for v in range(1, n + 1):
        if temp_avail[v]:
            final_iso.append(v)
            for neighbor in adj[v]:
                temp_avail[neighbor] = False

    return "1\n{}".format(' '.join(map(str, final_iso)))
