from functools import lru_cache

def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0].strip())
    strengths = list(map(int, lines[1].strip().split()))
    m = int(lines[2].strip())
    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].strip().split()
        actions.append((parts[0], int(parts[1])))

    @lru_cache(None)
    def solve(available, action_idx):
        if action_idx == m:
            return 0

        action_type, team = actions[action_idx]

        if action_type == 'p':
            if team == 1:
                best = -float('inf')
                for hero in available:
                    remaining_heroes = available[:]
                    remaining_heroes.remove(hero)
                    score = hero + solve(tuple(sorted(remaining_heroes)), action_idx + 1)
                    if score > best:
                        best = score
                return best
            else:
                best = float('inf')
                for hero in available:
                    remaining_heroes = available[:]
                    remaining_heroes.remove(hero)
                    score = -hero + solve(tuple(sorted(remaining_heroes)), action_idx + 1)
                    if score < best:
                        best = score
                return best
        else:  # ban
            if team == 1:
                best = -float('inf')
                for hero in available:
                    remaining_heroes = available[:]
                    remaining_heroes.remove(hero)
                    score = solve(tuple(sorted(remaining_heroes)), action_idx + 1)
                    if score > best:
                        best = score
                return best
            else:
