        # Check diamond-shaped squares (size s >= 2 means s cells from center in each direction)
        for r in range(n):
            for c in range(m):
                if matrix[r][c] != '1':
                    continue

                for s in range(2, min(n, m) // 2 + 2):
                    if r - s < 0 or r + s >= n or c - s < 0 or c + s >= m:
                        continue

                    border_ok = True

                    # Check right side (down-right diagonal)
                    for i in range(1, s):
                        if matrix[r + i][c + i] != '1':
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check left side (up-left diagonal)
                    for i in range(1, s):
                        if matrix[r - i][c - i] != '1':
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check bottom side (down-right diagonal from bottom apex)
                    for i in range(1, s):
                        if matrix[r + s + i - 1][c + s - i] != '1':
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check top side (up-left diagonal from top apex)
                    for i in range(1, s):
                        if matrix[r - s - i + 1][c - s + i] != '1':
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check for touching foreign 1s around the diamond center
                    touch_ok = True
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < m and matrix[nr][nc] == '1':
                                touch_ok = False
                                break
                        if not touch_ok:
                            break
                    if not touch_ok:
                        continue

                    count += 1

        results.append(str(count))

    return '\n'.join(results)
