    friend_names = set()
    for seg in segments:
        friend_names.update(seg)

    sorted_friends = sorted(friend_names)
    friend_to_idx = {f: i for i, f in enumerate(sorted_friends)}
    num_friends = len(sorted_friends)

    # Build conflict masks for maximum independent set
    conflict_mask = [0] * num_friends

    for seg in segments:
        nodes_in_seg = [friend_to_idx[f] for f in seg]
        for i in range(len(nodes_in_seg)):
            for j in range(i + 1, len(nodes_in_seg)):
                conflict_mask[nodes_in_seg[i]] |= (1 << nodes_in_seg[j])
                conflict_mask[nodes_in_seg[j]] |= (1 << nodes_in_seg[i])

    # Maximum Independent Set with pruning
    max_size = 0

    def dfs(idx, count, mask):
        nonlocal max_size

        if idx == num_friends:
            max_size = max(max_size, count)
            return

        # Pruning: if remaining nodes can't improve the best solution
        remaining = num_friends - idx
        if count + remaining <= max_size:
            return

        # Try excluding current node (order matters for pruning effectiveness)
        dfs(idx + 1, count, mask)

        # Try including current node if no conflict
        if not (mask & conflict_mask[idx]):
            dfs(idx + 1, count + 1, mask | (1 << idx))

    dfs(0, 0, 0)

    return str(max_size)
