        if cp2 == 0 and on_segment(b2, a1, b1): return True
        if cp3 == 0 and on_segment(a1, a2, b2): return True
        if cp4 == 0 and on_segment(b1, a2, b2): return True
        return False

    def is_polygon_edge(edge_i, edge_j):
        for k in range(n):
            other = (k + 1) % n
            if (edge_i == k and edge_j == other) or (edge_i == other and edge_j == k):
                return True
        return False

    def is_valid_triangle(i, k, j):
        if is_polygon_edge(i, k) or is_polygon_edge(k, j):
            return False
        for m in range(n):
            if m == i or m == k or m == j:
                continue
            if cross_product(coords[i], coords[k], coords[m]) == 0:
                return on_segment(coords[m], coords[i], coords[k]) or \
                       on_segment(coords[m], coords[k], coords[j]) or \
                       on_segment(coords[m], coords[i], coords[j])
        for m in range(n):
            other = (m + 1) % n
            if m == i or other == i or m == k or other == k or m == j or other == j:
                continue
            if segments_intersect(coords[i], coords[k], coords[m], coords[other]):
                return False
            if segments_intersect(coords[k], coords[j], coords[m], coords[other]):
                return False
        return True

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n
            for k in range(i + 1, j):
