    def count_prime_factors(n):
        count = 0
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                count += 1
                temp //= d
            d += 1
        if temp > 1:
            count += 1
        return count

    all_primes = set()
    for num in nums:
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                all_primes.add(d)
                temp //= d
